pragma solidity 0.8.25;

/// @dev timestamp indicating that an operation is done
uint256 constant _DONE_TIMESTAMP = uint256(1);

/// @dev minimum delay for timelocked operations
uint256 constant MIN_DELAY = 1 days;

/// @dev maximum delay for timelocked operations
uint256 constant MAX_DELAY = 30 days;

c474b9480850d08514c100b415efcbc962608c62.src/utils/Create2Helper.sol:
pragma solidity 0.8.25;

struct Create2Params {
    address creator;
    bytes creationCode;
    bytes constructorParams;
    bytes32 salt;
}

function calculateCreate2Address(
    address creator,
    bytes memory creationCode,
    bytes memory constructorParams,
    bytes32 salt
) pure returns (address) {
    return address(
        uint160(
            uint256(
                keccak256(
                    abi.encodePacked(
                        bytes1(0xff),
                        creator,
                        salt,
                        keccak256(
                            abi.encodePacked(creationCode, constructorParams)
                        )
                    )
                )
            )
        )
    );
}

function calculateCreate2Address(Create2Params memory params)
    pure
    returns (address)
{
    return address(
        uint160(
            uint256(
                keccak256(
                    abi.encodePacked(
                        bytes1(0xff),
                        params.creator,
                        params.salt,
                        keccak256(
                            abi.encodePacked(
                                params.creationCode, params.constructorParams
                            )
                        )
                    )
                )
            )
        )
    );
}

c474b9480850d08514c100b415efcbc962608c62.src/InstanceDeployer.sol:
pragma solidity 0.8.25;

import {SafeProxyFactory} from "@safe/proxies/SafeProxyFactory.sol";
import {ModuleManager} from "@safe/base/ModuleManager.sol";
import {OwnerManager} from "@safe/base/OwnerManager.sol";
import {GuardManager} from "@safe/base/GuardManager.sol";
import {IMulticall3} from "@interface/IMulticall3.sol";
import {SafeProxy} from "@safe/proxies/SafeProxy.sol";
import {Enum} from "@safe/common/Enum.sol";
import {Safe} from "@safe/Safe.sol";

import {Guard} from "src/Guard.sol";
import {Timelock} from "src/Timelock.sol";
import {TimelockFactory, DeploymentParams} from "src/TimelockFactory.sol";
import {
    calculateCreate2Address, Create2Params
} from "src/utils/Create2Helper.sol";

/// @notice deploy a completely set up instance of a contract
/// system for a user.

/// Relies on both the SafeProxyFactory and TimelockFactory to be deployed
/// before this contract.
/// Then calls into the SafeProxyFactory and TimelockFactory to create the
/// Safe and Timelock.

/// @notice the deployment process is as follows:
///
///    1. deploy the safe proxy with this contract as the owner from the proxy
///    factory
///      - if the safe has already been deployed the proxy factory will continue
///      deploying the system instance, this is to prevent front-running attacks
///      where a malicious user could deploy the safe before the system
///      instance to block the instance from ever being deployed to this chain
///    2. deploy the timelock contract with the new safe as the owner
///      - it should be impossible for the timelock to be deployed at the
///      correct address without being deployed by the timelock factory because
///      the factory uses the msg.sender for creating its salt, which would be
///      the instance deployer.
///
///    All of the following actions are batched into a single action
///  through multicall. The actions are as follows:
///
///    3. add the timelock as a module to the safe
///    4. add the guard to the safe
///    5. add all recovery spells as modules to the safe
///    6. rotate this contract as the safe owner off the safe and add the supplied
///    owners to the safe.
///    7. Update the proposal threshold on the final call performing the rotation.

struct NewInstance {
    /// safe information
    address[] owners;
    uint256 threshold;
    /// recovery spells are not part of the creation salt as that would create
    /// a circular dependency
    address[] recoverySpells;
    /// timelock information
    DeploymentParams timelockParams;
}

struct SystemInstance {
    SafeProxy safe;
    Timelock timelock;
}

contract InstanceDeployer {
    /// @notice safe proxy creation factory, address is the same across all chains
    address public immutable safeProxyFactory;

    /// @notice safe proxy logic contract, address is the same across all chains
    address public immutable safeProxyLogic;

    /// @notice timelock factory address, address is the same across all chains
    address public immutable timelockFactory;

    /// @notice Guard address, address is the same across all chains
    address public immutable guard;

    /// @notice MULTICALL3 address, address is the same across all chains
    address public immutable multicall3;

    /// @notice emitted when a new system instance is created
    /// @param safe address of the safe
    /// @param timelock address of the timelock
    /// @param creator address that created the system instance
    /// @param creationTime time the system instance was created in unix time
    event SystemInstanceCreated(
        address indexed safe,
        address indexed timelock,
        address indexed creator,
        uint256 creationTime
    );

    /// @param sender address that attempted to create the safe
    /// @param timestamp time the safe creation failed
    /// @param safeInitdata initialization data for the safe
    /// @param creationSalt salt used to create the safe
    event SafeCreationFailed(
        address indexed sender,
        uint256 indexed timestamp,
        address indexed safe,
        bytes safeInitdata,
        uint256 creationSalt
    );

    /// @notice initialize with all immutable variables
    constructor(
        address _safeProxyFactory,
        address _safeProxyLogic,
        address _timelockFactory,
        address _guard,
        address _multicall3
    ) {
        safeProxyFactory = _safeProxyFactory;
        safeProxyLogic = _safeProxyLogic;
        timelockFactory = _timelockFactory;
        guard = _guard;
        multicall3 = _multicall3;
    }

    /// callable only by the hot signer of the timelock
    /// this prevents a malicious user from deploying a system instance with
    /// calldata that was not intended to be whitelisted.

    /// @notice function to create a system instance that has the following
    /// contracts and configurations:
    /// 1. new safe created with specified owners and threshold
    /// 2. new timelock created owned by the safe
    /// 3. timelock is a module in the safe
    /// 4. the guard is configured on the safe as a guard
    /// 5. all recovery spells are added as modules on the safe
    /// 6. this contract is no longer an owner and threshold is updated to
    /// the threshold parameter passed
    /// A key system property is that deployments are deterministic across
    /// all chains. The same calldata on any EVM equivalent chain will generate
    /// the same safe and timelock address.
    /// @param instance configuration parameters
    function createSystemInstance(NewInstance memory instance)
        external
        returns (SystemInstance memory walletInstance)
    {
        address[] memory factoryOwner = new address[](1);
        factoryOwner[0] = address(this);

        bytes memory safeInitdata = abi.encodeWithSignature(
            "setup(address[],uint256,address,bytes,address,address,uint256,address)",
            factoryOwner,
            1,
            /// no to address because there are no external actions on
            /// initialization
            address(0),
            /// no data because there are no external actions on initialization
            "",
            /// no fallback handler allowed by Guard
            address(0),
            /// no payment token
            address(0),
            /// no payment amount
            0,
            /// no payment receiver because no payment amount
            address(0)
        );

        uint256 creationSalt = uint256(
            keccak256(
                abi.encode(
                    instance.owners,
                    instance.threshold,
                    instance.timelockParams.minDelay,
                    instance.timelockParams.expirationPeriod,
                    instance.timelockParams.pauser,
                    instance.timelockParams.pauseDuration,
                    instance.timelockParams.hotSigners
                )
            )
        );

        /// timelock salt is the result of the all params, so no one can
        /// front-run creation of the timelock with the same address on other
        /// chains
        instance.timelockParams.salt = bytes32(creationSalt);

        /// safe guard against front-running safe creation with the same
        /// address, init data and creation salt on other chains
        try SafeProxyFactory(safeProxyFactory).createProxyWithNonce(
            safeProxyLogic, safeInitdata, creationSalt
        ) returns (SafeProxy safeProxy) {
            walletInstance.safe = safeProxy;
        } catch {
            /// calculate salt just like the safe proxy factory does
            bytes32 salt = keccak256(
                abi.encodePacked(keccak256(safeInitdata), creationSalt)
            );
            walletInstance.safe = SafeProxy(
                payable(
                    calculateCreate2Address(
                        safeProxyFactory,
                        SafeProxyFactory(safeProxyFactory).proxyCreationCode(),
                        abi.encode(safeProxyLogic),
                        salt
                    )
                )
            );

            emit SafeCreationFailed(
                msg.sender,
                block.timestamp,
                address(walletInstance.safe),
                safeInitdata,
                creationSalt
            );
        }

        /// if front-running occurred, there should be no way for the safe to
        /// be created without the exact same address, which means init data
        /// set the owner of the safe to be this factory address.
        assert(Safe(payable(walletInstance.safe)).isOwner(address(this)));
        assert(Safe(payable(walletInstance.safe)).getOwners().length == 1);

        /// the factory uses the msg.sender for creating its salt, so there is
        /// no way to front-run the timelock creation
        walletInstance.timelock = Timelock(
            payable(
                TimelockFactory(timelockFactory).createTimelock(
                    address(walletInstance.safe), instance.timelockParams
                )
            )
        );

        require(
            walletInstance.timelock.hasRole(
                walletInstance.timelock.HOT_SIGNER_ROLE(), msg.sender
            ),
            "InstanceDeployer: sender must be hot signer"
        );

        walletInstance.timelock.initialize(
            instance.timelockParams.contractAddresses,
            instance.timelockParams.selectors,
            instance.timelockParams.startIndexes,
            instance.timelockParams.endIndexes,
            instance.timelockParams.datas
        );

        /// checks that contracts successfully deployed
        assert(address(walletInstance.timelock).code.length != 0);
        assert(address(walletInstance.safe).code.length != 0);

        /// 1. setGuard
        /// 2. enable timelock as a module in the safe
        IMulticall3.Call3[] memory calls3 = new IMulticall3.Call3[](
            2 + instance.recoverySpells.length + instance.owners.length
        );
        {
            uint256 index = 0;

            for (uint256 i = 0; i < calls3.length; i++) {
                calls3[i].target = address(walletInstance.safe);
                calls3[i].allowFailure = false;
            }

            calls3[index++].callData =
                abi.encodeWithSelector(GuardManager.setGuard.selector, guard);

            /// add the timelock as a module to the safe
            /// this enables the timelock to execute calls + delegate calls through
            /// the safe
            calls3[index++].callData = abi.encodeWithSelector(
                ModuleManager.enableModule.selector,
                address(walletInstance.timelock)
            );

            /// enable all recovery spells in the safe by adding them as modules
            for (uint256 i = 0; i < instance.recoverySpells.length; i++) {
                /// all recovery spells should be private at the time of safe
                /// creation, however we cannot enforce this except by excluding
                /// recovery spells that are not private.

                /// We cannot have a check here that recovery spells are private
                /// because if we did, and a recovery spell got activated, and it
                /// was activated on another chain where the system instance was
                /// deployed, and then the system instance was not deployed on this
                /// chain, then a malicious user could deploy the recovery spell
                /// before the system instance to block the instance from ever
                /// being deployed to this chain.
                calls3[index++].callData = abi.encodeWithSelector(
                    ModuleManager.enableModule.selector,
                    instance.recoverySpells[i]
                );
            }

            calls3[index++].callData = abi.encodeWithSelector(
                OwnerManager.swapOwner.selector,
                /// previous owner
                address(1),
                /// old owner (this address)
                address(this),
                /// new owner, the first owner the caller wants to add
                instance.owners[0]
            );

            /// - add owners with threshold of 1
            /// - only cover indexes 1 through newOwners.length - 1
            /// - leave the last index for the final owner which will adjust the
            /// threshold
            for (uint256 i = 1; i < instance.owners.length - 1; i++) {
                calls3[index++].callData = abi.encodeWithSelector(
                    OwnerManager.addOwnerWithThreshold.selector,
                    instance.owners[i],
                    1
                );
            }

            /// if there is only one owner, the threshold is set to 1
            /// if there are more than one owner, add the final owner with the
            /// updated threshold
            if (instance.owners.length > 1) {
                /// add final owner with the updated threshold
                /// if threshold is greater than the number of owners, that
                /// will be caught in the addOwnerWithThreshold function with
                /// error "GS201"
                calls3[index++].callData = abi.encodeWithSelector(
                    OwnerManager.addOwnerWithThreshold.selector,
                    instance.owners[instance.owners.length - 1],
                    instance.threshold
                );
            }

            /// ensure that the number of calls is equal to the index
            /// this is a safety check and should never be false
            assert(calls3.length == index);
        }

        bytes memory signature;
        /// craft the signature singing off on all of the multicall
        /// operations
        {
            bytes32 r = bytes32(uint256(uint160(address(this))));
            uint8 v = 1;

            assembly ("memory-safe") {
                /// Load free memory location
                let ptr := mload(0x40)

                /// We allocate memory for the return data by setting the free memory location to
                /// current free memory location + data size + 32 bytes for data size value

                ///         4 -> 82
                mstore(0x40, add(ptr, 97))
                ///         4 -> 179

                /// Store the size of the signature in the first 32 bytes:
                /// 65 (r + s + v)
                mstore(ptr, 65)

                ///
                ///                              Data Offsets
                ///
                ///                 --------------------------------------
                ///  bytes length   |      32     |   32  |  32   |   1  |
                ///                 --------------------------------------
                ///      bytes      |     0-31    | 32-63 | 64-95 |  96  |
                ///                 --------------------------------------
                ///      data       | length = 65 |   r   |   s   |   v  |
                ///                 --------------------------------------
                ///

                /// store r at offset 32 to 64 in the allocated pointer
                mstore(add(ptr, 0x20), r)

                /// no need to store s, this should be 0 bytes

                /// store v at offset 96 to 97 in the allocated pointer
                mstore8(add(ptr, 0x60), v)

                /// Point the signature data to the correct memory location
                signature := ptr
            }
        }

        require(
            Safe(payable(walletInstance.safe)).execTransaction(
                multicall3,
                0,
                abi.encodeWithSelector(IMulticall3.aggregate3.selector, calls3),
                Enum.Operation.DelegateCall,
                0,
                0,
                0,
                address(0),
                payable(0),
                signature
            ),
            "InstanceDeployer: Safe delegate call failed"
        );

        emit SystemInstanceCreated(
            address(walletInstance.safe),
            address(walletInstance.timelock),
            msg.sender,
            block.timestamp
        );
    }
}

c474b9480850d08514c100b415efcbc962608c62.src/RecoverySpell.sol:
pragma solidity 0.8.25;

import {EIP712} from
    "@openzeppelin-contracts/contracts/utils/cryptography/EIP712.sol";
import {ECDSA} from
    "@openzeppelin-contracts/contracts/utils/cryptography/ECDSA.sol";

import {Enum} from "@safe/common/Enum.sol";
import {Safe} from "@safe/Safe.sol";

import {IMulticall3} from "@interface/IMulticall3.sol";
import {OwnerManager} from "@safe/base/OwnerManager.sol";
import {ModuleManager} from "@safe/base/ModuleManager.sol";

/// @notice if two recovery spells with exactly the same parameters are
/// deployed for the same safe, the domain separator will not be the same
/// because the address of the recovery spell contract is different.
/// This is important as it prevents signature re-use across different
/// recovery spells and chains for the same safe.
contract RecoverySpell is EIP712("Recovery Spell", "0.1.0") {
    /// -------------------------------------------------------
    /// -------------------------------------------------------
    /// ------------------ STORAGE VARIABLES ------------------
    /// -------------------------------------------------------
    /// -------------------------------------------------------

    /// @notice the new owners of the contract once the spell is cast
    /// @dev starts off with non zero array if created by factory
    /// and then is deleted after recovery execution
    address[] public owners;

    /// @notice the time the recovery was initiated
    /// @dev value can only go from 0 to non zero when owner calls
    /// goes from block.timestamp (always lt type(uint32).max)
    /// to type(uint256).max
    /// value can only ever increase
    uint256 public recoveryInitiated;

    /// -------------------------------------------------------
    /// -------------------------------------------------------
    /// ---------------------- IMMUTABLES ---------------------
    /// -------------------------------------------------------
    /// -------------------------------------------------------

    /// @notice the address to recover
    Safe public immutable safe;

    /// @notice the threshold of owners required to execute transactions
    /// after the recovery is executed
    /// threshold must be lte the number of owners
    uint256 public immutable threshold;

    /// @notice the number of new owner signatures required to execute the
    /// recovery process. This is to prevent a single owner from initiating
    /// the recovery process without the consent of the other owners
    uint256 public immutable recoveryThreshold;

    /// @notice the time delay required before the recovery transaction
    /// can be executed
    uint256 public immutable delay;

    /// -------------------------------------------------------
    /// -------------------------------------------------------
    /// ---------------------- CONSTANTS ----------------------
    /// -------------------------------------------------------
    /// -------------------------------------------------------

    /// @notice the multicall3 contract address
    address public constant MULTICALL3 =
        0xcA11bde05977b3631167028862bE2a173976CA11;

    /// @notice the sentinel address that all linked lists start with
    address public constant SENTINEL = address(0x1);

    /// @notice the recovery type hash for the EIP712 domain separator
    bytes32 public constant RECOVERY_TYPEHASH = keccak256(
        "Recovery(address safe,uint256 newSafeThreshold,uint256 newRecoveryThreshold,uint256 delay)"
    );

    /// -------------------------------------------------------
    /// -------------------------------------------------------
    /// ------------------------ EVENTS -----------------------
    /// -------------------------------------------------------
    /// -------------------------------------------------------

    /// @notice event emitted when the recovery is initiated
    /// @param time the time the recovery was initiated
    /// @param caller the address that initiated the recovery
    event RecoveryInitiated(uint256 indexed time, address indexed caller);

    /// @notice event emitted when the recovery is executed
    /// @param time the time the recovery was executed
    event SafeRecovered(uint256 indexed time);

    /// @notice it is of critical importance that the delay is shorter
    /// than the timelock delay so that a recovery action can be executed
    /// before the timelock delay expires if need be. There is no way to enforce
    /// this in the contract, so it is up to the deployer to ensure that the
    /// delay is shorter than the timelock delay
    /// @param _owners the new owners of the contract if recovery is executed
    /// @param _safe the address to recover
    /// @param _safeThreshold number of owners required to execute transactions on the safe
    /// @param _recoveryThreshold number of signers required to execute recovery transaction
    /// @param _delay time required before the recovery transaction can be executed
    constructor(
        address[] memory _owners,
        address _safe,
        uint256 _safeThreshold,
        uint256 _recoveryThreshold,
        uint256 _delay
    ) {
        /// no checks on parameters as all valid recovery spells are
        /// deployed from the factory which will not allow a recovery
        /// spell to be created that does not have valid parameters.
        /// A recovery spell can only be created by the factory if the Safe has
        /// already been created on the chain the RecoverySpell is being
        /// deployed on.
        owners = _owners;
        safe = Safe(payable(_safe));
        threshold = _safeThreshold;
        recoveryThreshold = _recoveryThreshold;
        delay = _delay;

        recoveryInitiated = block.timestamp;

        emit RecoveryInitiated(block.timestamp, msg.sender);
    }

    /// @notice get the owners of the contract
    function getOwners() external view returns (address[] memory) {
        return owners;
    }

    /// @notice get the digest for the EIP712 domain separator
    /// @return the digest for the EIP712 domain separator
    function getDigest() public view returns (bytes32) {
        return keccak256(
            abi.encodePacked(
                "\x19\x01",
                _domainSeparatorV4(),
                keccak256(
                    abi.encode(
                        RECOVERY_TYPEHASH,
                        safe,
                        threshold,
                        recoveryThreshold,
                        delay
                    )
                )
            )
        );
    }

    /// @notice execute the recovery process, can only be called
    /// after the recovery delay has passed. Callable by any address
    /// @param previousModule the address of the previous module
    /// if the previous module is incorrect, this function will fail
    ///
    /// this function executes actions in the following order:
    ///   1). remove all but final existing owner, sets owner threshold to 1
    ///   2). swap final existing owner for the first new owner
    ///   3). add the remaining new owners to the safe
    ///   4). update the quorum to the new value
    ///   4). remove the recovery module from the safe
    function executeRecovery(
        address previousModule,
        uint8[] calldata v,
        bytes32[] calldata r,
        bytes32[] calldata s
    ) external {
        /// checks
        require(
            recoveryInitiated != type(uint256).max,
            "RecoverySpell: Already recovered"
        );

        /// fails if recovery already executed due to math overflow
        /// even if delay is 0, uint256.max + 1 will always revert
        /// recovery initiated will always be lte block timestamp before the recovery is executed
        require(
            block.timestamp > recoveryInitiated + delay,
            "RecoverySpell: Recovery not ready"
        );
        require(
            v.length == r.length && r.length == s.length,
            "RecoverySpell: Invalid signature parameters"
        );
        /// if there are not enough signers, even if all signatures are
        /// valid and not duplicated, there is no possibility of this being
        /// enough to execute the recovery.
        require(
            recoveryThreshold <= v.length,
            "RecoverySpell: Not enough signatures"
        );

        for (uint256 i = 0; i < owners.length; i++) {
            address owner = owners[i];
            assembly ("memory-safe") {
                tstore(owner, 1)
            }
        }

        /// duplication and validity checks
        /// ensure the signatures are
        /// 1. valid signatures
        /// 2. unique signers
        /// 3. recovery owners about to be added to the safe

        /// check if an address that provided a signature is an owner
        /// in storage, then remove that address from used addresses
        /// to prevent the same owner passing multiple signatures.

        bytes32 digest = getDigest();
        for (uint256 i = 0; i < v.length; i++) {
            address recoveredAddress = ECDSA.recover(digest, v[i], r[i], s[i]);
            bool valid;

            assembly ("memory-safe") {
                valid := tload(recoveredAddress)
                if eq(valid, 1) { tstore(recoveredAddress, 0) }
            }

            /// if the address of the signer was not in storage, the value will
            /// be 0 and the require will fail.
            /// if the address of the signer duplicated signatures, the value
            /// will be 0 on the second retrieval and the require will fail.
            require(
                valid && recoveredAddress != address(0),
                "RecoverySpell: Invalid signature"
            );
        }

        /// @notice execute the recovery process, can only be called
        /// after the recovery delay has passed. Callable by any address

        /// @param previousModule the address of the previous module
        /// if the previous module is incorrect, this function will fail
        ///
        /// this function executes actions in the following order:
        ///   1). remove all but final existing owner, set owner threshold to 1
        ///   2). swap final existing owner for the first new owner
        ///   3). add the remaining new owners to the safe, with the
        ///   last owner being added updating the threshold to the new value
        ///   4). remove the recovery module from the safe
        address[] memory existingOwners = safe.getOwners();
        uint256 existingOwnersLength = existingOwners.length;

        /// + 1 is for the module removal
        /// new owner length = 1
        /// existing owner length = 1
        IMulticall3.Call3[] memory calls3 =
            new IMulticall3.Call3[](owners.length + existingOwnersLength + 1);

        uint256 index = 0;

        /// build interactions

        /// remove all existing owners except the last one
        for (uint256 i = 0; i < existingOwnersLength - 1; i++) {
            calls3[index++].callData = abi.encodeWithSelector(
                OwnerManager.removeOwner.selector,
                SENTINEL,
                existingOwners[i],
                1
            );
        }

        calls3[index++].callData = abi.encodeWithSelector(
            OwnerManager.swapOwner.selector,
            SENTINEL,
            existingOwners[existingOwnersLength - 1],
            owners[0]
        );

        /// only cover indexes 1 through new owners length
        for (uint256 i = 1; i < owners.length; i++) {
            calls3[index++].callData = abi.encodeWithSelector(
                OwnerManager.addOwnerWithThreshold.selector, owners[i], 1
            );
        }

        /// add new owner with the updated threshold
        calls3[index++].callData = abi.encodeWithSelector(
            OwnerManager.changeThreshold.selector, threshold
        );

        calls3[index].callData = abi.encodeWithSelector(
            ModuleManager.disableModule.selector, previousModule, address(this)
        );

        for (uint256 i = 0; i < calls3.length; i++) {
            calls3[i].allowFailure = false;
            calls3[i].target = address(safe);
        }

        /// effects
        /// now impossible to call initiate recovery as owners array is empty
        delete owners;

        /// array length is set to 0 impossible for executeRecovery to be
        /// callable again as the require check will always revert
        recoveryInitiated = type(uint256).max;

        /// interactions

        require(
            safe.execTransactionFromModule(
                MULTICALL3,
                0,
                abi.encodeWithSelector(IMulticall3.aggregate3.selector, calls3),
                Enum.Operation.DelegateCall
            ),
            "RecoverySpell: Recovery failed"
        );

        emit SafeRecovered(block.timestamp);
    }
}

c474b9480850d08514c100b415efcbc962608c62.src/RecoverySpellFactory.sol:
pragma solidity 0.8.25;

import {RecoverySpell} from "@src/RecoverySpell.sol";
import {calculateCreate2Address} from "src/utils/Create2Helper.sol";

/// @notice factory contract to create new RecoverySpell contracts
/// Contract addresses can be determined in advance with different
/// parameters, salts and parameters.
///
/// Edge Cases:
///    If the safe address has no bytecode, or is incorrectly
///    specified, then the recovery spell address will be calculated
///    correctly, but it will not actually map to the corresponding
///    contract.
///
/// Contract Paramters:
///   - salt: a random number used to create the contract address
///   - owners: the new owners of the contract
///   - safe: the address of the safe to recover
///   - threshold: the number of owners required to execute transactions on
//    the new safe
///   - recoveryThreshold: the number of owners required to execute recovery
///   transactions on the new safe. If 0, no private keys are needed to recover
///   the safe.
///   - delay: the time required before the recovery transaction can be executed
///   on the new safe. can be 0 to execute immediately

contract RecoverySpellFactory {
    /// @notice emitted when a new recovery spell is created
    /// @param recoverySpell the address of the new recovery spell
    /// @param safe the address of the safe that is being recovered
    /// with the spell
    event RecoverySpellCreated(
        address indexed recoverySpell, address indexed safe
    );

    /// @notice create a new RecoverySpell contract using CREATE2
    /// @param salt the salt used to create the contract
    /// @param owners the owners of the contract
    /// @param safe to recover with the spell
    /// @param threshold of owners required to execute transactions
    /// @param recoveryThreshold of owners required to execute recovery transactions
    /// @param delay time required before the recovery transaction can be executed
    function createRecoverySpell(
        bytes32 salt,
        address[] memory owners,
        address safe,
        uint256 threshold,
        uint256 recoveryThreshold,
        uint256 delay
    ) external returns (RecoverySpell recovery) {
        _paramChecks(owners, threshold, recoveryThreshold, delay);
        /// no checks on parameters as all valid recovery spells are
        /// deployed from the factory which will not allow a recovery
        /// spell to be created that does not have valid parameters
        require(safe.code.length != 0, "RecoverySpell: safe non-existent");

        /// duplicate owner check
        for (uint256 i = 0; i < owners.length; i++) {
            /// not touching memory, we only use the stack and transient storage
            /// so we can use memory-safe for the assembly block
            address owner = owners[i];
            bool found;
            assembly ("memory-safe") {
                found := tload(owner)
                /// save a write to transient storage if the owner is found
                if eq(found, 0) { tstore(owner, 1) }
            }

            require(!found, "RecoverySpell: Duplicate owner");
        }

        recovery = new RecoverySpell{salt: salt}(
            owners, safe, threshold, recoveryThreshold, delay
        );

        emit RecoverySpellCreated(address(recovery), address(safe));
    }

    /// @notice calculate the address of a new RecoverySpell contract
    /// @param salt the salt used to create the contract
    /// @param safe to recover with the spell
    /// @param owners the owners of the contract
    /// @param threshold of owners required to execute transactions
    /// @param delay time required before the recovery transaction can be executed
    function calculateAddress(
        bytes32 salt,
        address[] memory owners,
        address safe,
        uint256 threshold,
        uint256 recoveryThreshold,
        uint256 delay
    ) external view returns (address predictedAddress) {
        _paramChecks(owners, threshold, recoveryThreshold, delay);

        /// duplicate owner check
        for (uint256 i = 0; i < owners.length; i++) {
            for (uint256 j = i + 1; j < owners.length; j++) {
                require(
                    owners[i] != owners[j], "RecoverySpell: Duplicate owner"
                );
            }
        }

        predictedAddress = calculateCreate2Address(
            address(this),
            type(RecoverySpell).creationCode,
            abi.encode(owners, safe, threshold, recoveryThreshold, delay),
            salt
        );
    }

    /// @notice check the parameters of the RecoverySpell contract
    /// @param owners the owners of the contract
    /// @param threshold of owners required to execute transactions
    /// @param recoveryThreshold of owners required to execute recovery transactions
    /// @param delay time required before the recovery transaction can be executed
    function _paramChecks(
        address[] memory owners,
        uint256 threshold,
        uint256 recoveryThreshold,
        uint256 delay
    ) private pure {
        require(
            threshold <= owners.length,
            "RecoverySpell: Threshold must be lte number of owners"
        );
        require(
            recoveryThreshold <= owners.length,
            "RecoverySpell: Recovery threshold must be lte number of owners"
        );

        require(threshold != 0, "RecoverySpell: Threshold must be gt 0");
        require(delay <= 365 days, "RecoverySpell: Delay must be lte a year");
        for (uint256 i = 0; i < owners.length; i++) {
            require(owners[i] != address(0), "RecoverySpell: Owner cannot be 0");
        }
    }
}

